/* AI Memory for each website and for connected agents (V round), run after 106. Adds to `ai_memories`: `kind` (voice, design, like, dislike, fact or preference), `source_name` (which connected agent kept a note, up to 80 characters), and a third source, 'agent', for a note kept by Claude Code, Codex or another tool connected over MCP. A second index finds one website's notes. Row level security is unchanged: a signed in person reads, adds and deletes only their own, and a website's notes only for a website of theirs; nobody can change one in place. No existing row changes. Until it runs, notes keep their words and scope without a kind, and a connected agent's note is kept as Storelib AI's. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.ai_memories') IS NULL THEN RAISE NOTICE 'ai memory sources: run part 106 first.'; RETURN; END IF; ALTER TABLE public.ai_memories ADD COLUMN IF NOT EXISTS kind text; ALTER TABLE public.ai_memories ADD COLUMN IF NOT EXISTS source_name text; ALTER TABLE public.ai_memories DROP CONSTRAINT IF EXISTS ai_memories_kind_check; ALTER TABLE public.ai_memories ADD CONSTRAINT ai_memories_kind_check CHECK (kind IS NULL OR kind IN ('voice', 'design', 'like', 'dislike', 'fact', 'preference')); ALTER TABLE public.ai_memories DROP CONSTRAINT IF EXISTS ai_memories_source_name_check; ALTER TABLE public.ai_memories ADD CONSTRAINT ai_memories_source_name_check CHECK (source_name IS NULL OR length(source_name) BETWEEN 1 AND 80); ALTER TABLE public.ai_memories DROP CONSTRAINT IF EXISTS ai_memories_source_check; ALTER TABLE public.ai_memories ADD CONSTRAINT ai_memories_source_check CHECK (source IN ('creator', 'assistant', 'agent')); CREATE INDEX IF NOT EXISTS ai_memories_install_idx ON public.ai_memories (install_id, created_at DESC) WHERE install_id IS NOT NULL; ALTER TABLE public.ai_memories ENABLE ROW LEVEL SECURITY; REVOKE UPDATE ON public.ai_memories FROM authenticated, anon; REVOKE ALL ON public.ai_memories FROM anon; END $do$;
notify pgrst, 'reload schema';
